function [m] = attitude_from_aoa(vrel, aoa_deg, sideslip_deg)
%ATTITUDE_FROM_AOA  dgeom.attitudeFromAoA(vrel, aoa_deg, sideslip_deg): the ram attitude pitched by the angle of attack about body y,
%   then yawed by the sideslip about body z [deg].
%   vrel: real[1][3] (passed a plain number)
%   aoa_deg: real[1] (passed a plain number)
%   sideslip_deg: real[1] (passed a plain number)
%   returns m: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 3);
    rram = asils.models.drag.ram_attitude(vrel);
    a = asils.models.timescales.deg2rad(aoa_deg);
    b = asils.models.timescales.deg2rad(sideslip_deg);
    ry = [([cos(a); 0; sin(a)]).'; ([0; 1; 0]).'; ([(-(sin(a))); 0; cos(a)]).'];
    rz = [([cos(b); (-(sin(b))); 0]).'; ([sin(b); cos(b); 0]).'; ([0; 0; 1]).'];
    m = asils.pc.mm(asils.pc.mm(rram, ry), rz);
end
